304	function getStatusBadge(status: string, t: ReturnType<typeof useT>, refundAmount?: number) {
305	  switch (status) {
306	    case "confirmed":
307	      return <Badge className="bg-green-500 hover:bg-green-600 text-white text-xs"><CheckCircle2 className="w-3 h-3 mr-1" />{t("bookings.status.confirmed")}</Badge>;
308	    case "pending":
309	      return <Badge variant="secondary" className="bg-yellow-500/20 text-yellow-700 dark:text-yellow-400 text-xs"><Clock className="w-3 h-3 mr-1" />{t("bookings.status.pending")}</Badge>;
310	    case "awaiting_players":
311	      return <Badge variant="secondary" className="bg-blue-500/20 text-blue-700 dark:text-blue-400 text-xs"><Users className="w-3 h-3 mr-1" />Laukiama žaidėjų</Badge>;
312	    case "cancelled": {
313	      const r = Number(refundAmount ?? 0);
314	      const label = r > 0
315	        ? `${t("bookings.status.cancelled")} · ${t("bookings.cancel.refunded")} €${r.toFixed(2)}`
316	        : `${t("bookings.status.cancelled")} · ${t("bookings.cancel.noRefund")}`;
317	      return <Badge variant="destructive" className="text-xs"><XCircle className="w-3 h-3 mr-1" />{label}</Badge>;
318	    }
319	    default:
320	      return <Badge variant="outline" className="text-xs">{status}</Badge>;
321	  }
322	}
323	
324	function BookingCard({
325	  booking,
326	  isUpcoming,
327	  onRate,
328	  onCancel,
329	  cancelling,
330	}: {
331	  booking: BookingItem;
332	  isUpcoming: boolean;
333	  onRate: () => void;
334	  onCancel: () => void;
335	  cancelling: boolean;
336	}) {
337	  const t = useT();
338	  const [, setLocation] = useLocation();
339	
340	  const dateLabel = format(booking.date, "yyyy-MM-dd");
341	  const dayLabel = format(booking.date, "EEEE", { locale: lt });
342	  const createdLabel = booking.createdAt
343	    ? format(new Date(booking.createdAt), "yyyy-MM-dd HH:mm")
344	    : null;
345	
346	  return (
347	    <div
348	      className="bg-card border rounded-xl p-4 space-y-3 cursor-pointer hover:border-primary/40 hover:shadow-sm transition-all group"
349	      onClick={() => setLocation(`/bookings/${booking.id}`)}
350	    >
351	      {/* Top row: court name + status */}
352	      <div className="flex items-start justify-between gap-2">
353	        <div className="min-w-0">
354	          <p className="font-semibold text-sm group-hover:text-primary transition-colors truncate">
355	            {booking.courtName || `Kortas #${booking.courtId}`}
356	          </p>
357	        </div>
358	        <div className="flex items-center gap-1.5 shrink-0">
359	          {getStatusBadge(booking.status, t, booking.refundAmount)}
360	          <ChevronRight className="w-4 h-4 text-muted-foreground/50" />
361	        </div>
362	      </div>
363	
364	      {/* Date/time + price row */}
365	      <div className="flex items-center gap-4 text-sm text-muted-foreground">
366	        <span className="flex items-center gap-1.5">
367	          <Calendar className="w-3.5 h-3.5" />
368	          <span className="capitalize">{dayLabel},</span>
369	          <span>{dateLabel}</span>
370	        </span>
371	        <span className="flex items-center gap-1">
372	          <Clock className="w-3.5 h-3.5" />
373	          {booking.startTime} – {booking.endTime}
374	        </span>
375	      </div>
376	      {createdLabel && (
377	        <div className="text-xs text-muted-foreground/70">
378	          {t("bookings.bookedAt")}: {createdLabel}
379	        </div>
380	      )}
381	
382	      {/* Split badge */}
383	      {booking.isSplit && (
384	        <div className="flex items-start gap-1.5 text-xs rounded-lg bg-blue-500/10 border border-blue-400/20 px-2.5 py-2">
385	          <Users className="w-3.5 h-3.5 text-blue-600 dark:text-blue-400 shrink-0 mt-0.5" />
386	          <div className="space-y-0.5">
387	            <div className="text-blue-700 dark:text-blue-400 font-medium">Bendras mokėjimas</div>
388	            <div className="text-blue-600/80 dark:text-blue-400/70">
389	              Jūsų dalis:{" "}
390	              <span className="font-semibold">
391	                {booking.pricePerSlot != null ? `€${Number(booking.pricePerSlot).toFixed(2)}` : "—"}
392	              </span>
393	              {" · "}Viso:{" "}
394	              <span className="font-semibold">
395	                €{Number(booking.totalPrice).toFixed(2)}
396	              </span>
397	              {" · "}Liko surinkti:{" "}
398	              <span className="font-semibold text-orange-500 dark:text-orange-400">
399	                €{Math.max(0, Number(booking.totalPrice) - Number(booking.pricePerSlot ?? 0)).toFixed(2)}
400	              </span>
401	            </div>
402	          </div>
403	        </div>
404	      )}
405	
406	      {/* Price + actions */}
407	      <div className="flex items-center justify-between pt-1 border-t border-border/50">
408	        <div className="flex flex-col">
409	          <span className="text-sm font-semibold">
410	            {booking.isSplit && booking.pricePerSlot != null
411	              ? (booking.pricePerSlot > 0 ? `€${Number(booking.pricePerSlot).toFixed(2)}` : "Nemokama")
412	              : (booking.totalPrice > 0 ? `€${Number(booking.totalPrice).toFixed(2)}` : "Nemokama")}
413	          </span>
414	          {booking.isSplit && booking.pricePerSlot != null && (
415	            <span className="text-[10px] text-muted-foreground">iš €{Number(booking.totalPrice).toFixed(2)} viso</span>
416	          )}
417	        </div>
418	        <div className="flex gap-2" onClick={e => e.stopPropagation()}>
419	          {!isUpcoming && booking.status === "confirmed" && (
420	            <Button
421	              variant="outline"
422	              size="sm"
423	              className="text-yellow-600 hover:text-yellow-700 border-yellow-200 hover:bg-yellow-50 dark:border-yellow-900 dark:hover:bg-yellow-900/20 gap-1 h-8 text-xs"
424	              onClick={onRate}
425	            >
426	              <Star className="h-3 w-3" />
427	              {t("bookings.rate")}
428	            </Button>
429	          )}
430	          {isUpcoming && (booking.status === "confirmed" || booking.status === "awaiting_players") && (
431	            <Button
432	              variant="ghost"
433	              size="sm"
434	              className="text-destructive hover:text-destructive hover:bg-destructive/10 h-8 text-xs"
435	              onClick={onCancel}
436	              disabled={cancelling}
437	            >
438	              {t("bookings.cancel")}
439	            </Button>
440	          )}
441	        </div>
442	      </div>
443	    </div>
444	  );
445	}
