447	export default function Bookings() {
448	  const t = useT();
449	  const [tab, setTab] = useState<"upcoming" | "past">("upcoming");
450	  const [sortKey, setSortKey] = useState<SortKey>("dateAsc");
451	  const [splitOnly, setSplitOnly] = useState(false);
452	  const [ratingBooking, setRatingBooking] = useState<{
453	    id: number; courtName?: string; courtId: number; customerName: string;
454	  } | null>(null);
455	  const [cancelTargetId, setCancelTargetId] = useState<number | null>(null);
456	
457	  const { data: bookings, isLoading } = useListBookings({});
458	  const cancelBooking = useCancelBooking();
459	  const queryClient = useQueryClient();
460	  const { toast } = useToast();
461	
462	  const handleCancelConfirmed = async (id: number) => {
463	    try {
464	      const result = await cancelBooking.mutateAsync({ id });
465	      const refunded = Number((result as any)?.refundAmount ?? 0);
466	      toast({
467	        title: t("bookings.status.cancelled"),
468	        description: refunded > 0
469	          ? t("bookings.cancel.toastRefunded").replace("{amount}", refunded.toFixed(2))
470	          : t("bookings.cancel.toastNoRefund"),
471	      });
472	      queryClient.invalidateQueries({ queryKey: getListBookingsQueryKey() });
473	      queryClient.invalidateQueries({ queryKey: ["court-activity"] });
474	      queryClient.invalidateQueries({
475	        predicate: (q) => Array.isArray(q.queryKey) && q.queryKey.some(
476	          (k) => typeof k === "string" && k.includes("/availability"),
477	        ),
478	      });
479	    } catch {
480	      toast({ title: "Klaida", variant: "destructive" });
481	    }
482	  };
483	
484	  const today = new Date();
485	  today.setHours(0, 0, 0, 0);
486	
487	  const sorted = (bookings ?? []).slice().sort((a, b) => {
488	    if (sortKey === "createdDesc" || sortKey === "createdAsc") {
489	      const ca = a.createdAt ? new Date(a.createdAt).getTime() : 0;
490	      const cb = b.createdAt ? new Date(b.createdAt).getTime() : 0;
491	      return sortKey === "createdDesc" ? cb - ca : ca - cb;
492	    }
493	    const da = new Date(a.date).getTime();
494	    const db2 = new Date(b.date).getTime();
495	    if (da !== db2) return sortKey === "dateAsc" ? da - db2 : db2 - da;
496	    return sortKey === "dateAsc"
497	      ? a.startTime.localeCompare(b.startTime)
498	      : b.startTime.localeCompare(a.startTime);
499	  });
500	
501	  const localCancelledIds: number[] = (() => {
502	    try { return JSON.parse(sessionStorage.getItem("cancelledBookingIds") ?? "[]"); } catch { return []; }
503	  })();
504	  const startMs = (b: typeof sorted[number]) => {
505	    const dt = new Date(b.date);
506	    const [hh, mm] = (b.startTime ?? "00:00").split(":").map(Number);
507	    dt.setHours(hh || 0, mm || 0, 0, 0);
508	    return dt.getTime();
509	  };
510	  const nowMs = Date.now();
511	  const upcomingBookings = sorted.filter(b => {
512	    return startMs(b) > nowMs && b.status !== "cancelled" && !localCancelledIds.includes(b.id);
513	  });
514	
515	  const pastBookings = sorted.filter(b => {
516	    return startMs(b) <= nowMs || b.status === "cancelled";
517	  });
518	
519	  const allDisplayed = tab === "upcoming" ? upcomingBookings : pastBookings;
520	  const displayed = splitOnly ? allDisplayed.filter(b => (b as any).isSplit) : allDisplayed;
521	
522	  return (
523	    <Layout>
524	      <div className="container mx-auto px-4 py-8 max-w-2xl">
525	        <div className="mb-6">
526	          <h1 className="text-2xl font-bold tracking-tight">{t("bookings.title")}</h1>
527	          <p className="text-muted-foreground mt-1 text-sm">{t("bookings.subtitle")}</p>
528	        </div>
529	
530	        {/* Tabs + Sort */}
531	        <div className="flex items-center justify-between gap-3 mb-6 flex-wrap">
