199	    return;
200	  }
201	
202	  // ── Working hours validation ────────────────────────────────────────────────
203	  if (court.workingHours) {
204	    try {
205	      const wh = JSON.parse(court.workingHours) as Record<string, { open: string; close: string; closed: boolean }>;
206	      const dayConfig = wh[String(dayOfWeek)];
207	      if (dayConfig) {
