224	  // ── Compute server-side price using per-slot pricing (same logic as availability endpoint) ──
225	  // This can be done outside the transaction since pricing config is owner-managed, not concurrent.
226	  const pricingEntries = await db.select()
227	    .from(courtPricingTable)
228	    .where(and(
229	      eq(courtPricingTable.courtId, parsed.data.courtId),
230	      eq(courtPricingTable.dayOfWeek, dayOfWeek),
231	    ));
232	
233	  const pricingMap = new Map(pricingEntries.map(e => [e.startTime, Number(e.price)]));
234	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
