262	
263	      // ── Conflict check (inside lock) ──
264	      const [conflictingBookings, conflictingBlocked] = await Promise.all([
265	        tx.select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
266	          .from(bookingsTable)
