292	          throw new BookingConflictError(409, { error: "Requested time slot is not available", code: "SLOT_UNAVAILABLE" });
293	        }
294	      }
295	
296	      for (const b of conflictingBlocked) {
297	        const bStart = toMin(b.startTime);
298	        const bEnd = toMin(b.endTime);
299	        if (reqStartMin < bEnd && reqEndMin > bStart) {
300	          throw new BookingConflictError(409, { error: "Requested time slot is blocked", code: "SLOT_BLOCKED" });
301	        }
302	      }
303	
304	      // ── Equipment availability (inside lock, same consistent snapshot) ──
305	      let equipmentCost = 0;
306	      let validatedRentedItems: string | null = null;
307	      if (parsed.data.rentedItems) {
308	        try {
309	          const clientItems: Array<{ name: string; quantity?: number }> = JSON.parse(parsed.data.rentedItems);
310	          const courtEquipment: Array<{ name: string; pricePerSlot?: number; pricePerBooking?: number; stock: number }> =
311	            court.rentableItems ? JSON.parse(court.rentableItems) : [];
312	
313	          const existingBookings = await tx
314	            .select({ rentedItems: bookingsTable.rentedItems, startTime: bookingsTable.startTime, endTime: bookingsTable.endTime, status: bookingsTable.status })
315	            .from(bookingsTable)
316	            .where(and(eq(bookingsTable.courtId, parsed.data.courtId), eq(bookingsTable.date, dateStr0)));
317	          const bookedQty: Record<string, number> = {};
318	          for (const b of existingBookings) {
319	            if (!b.rentedItems || b.status === "cancelled") continue;
320	            const bStart = toMin(b.startTime);
321	            const bEnd = toMin(b.endTime);
322	            if (bEnd <= reqStartMin || bStart >= reqEndMin) continue;
323	            const items: Array<{ name: string; quantity: number }> = JSON.parse(b.rentedItems);
324	            for (const item of items) {
325	              bookedQty[item.name] = (bookedQty[item.name] ?? 0) + item.quantity;
326	            }
327	          }
328	
329	          const serverValidated: Array<{ name: string; pricePerSlot: number; quantity: number }> = [];
330	          for (const ci of clientItems) {
331	            const canonical = courtEquipment.find(e => e.name === ci.name);
332	            if (!canonical) continue;
333	            const pricePerSlot = canonical.pricePerSlot ?? canonical.pricePerBooking ?? 0;
334	            const qty = Math.max(1, Math.min(Math.floor(ci.quantity ?? 1), 20));
335	            const alreadyBooked = bookedQty[ci.name] ?? 0;
336	            if (alreadyBooked + qty > canonical.stock) {
337	              throw new BookingConflictError(409, {
338	                error: `Įranga "${ci.name}" nebepasiekiama: likę ${Math.max(0, canonical.stock - alreadyBooked)} vnt.`,
339	                code: "EQUIPMENT_UNAVAILABLE",
340	                item: ci.name,
341	                available: Math.max(0, canonical.stock - alreadyBooked),
342	              });
343	            }
344	            serverValidated.push({ name: canonical.name, pricePerSlot, quantity: qty });
345	            equipmentCost += pricePerSlot * qty * slotCount;
346	          }
347	          if (serverValidated.length > 0) validatedRentedItems = JSON.stringify(serverValidated);
348	        } catch (e) {
349	          if (e instanceof BookingConflictError) throw e;
350	          console.error("[bookings] equipment validation error:", e);
351	        }
352	      }
353	
354	      const totalPrice = courtPrice + equipmentCost;
355	
356	      // ── Insert inside the same transaction ──
357	      // Guests (no Clerk session) get a management_token so they can later view & cancel
358	      // their booking via /api/guest/bookings/:token. Authenticated users use their session.
359	      const managementToken = bookerUserId ? null : generateManagementToken();
360	
361	      const [inserted] = await tx.insert(bookingsTable).values({
362	        courtId: parsed.data.courtId,
363	        bookerUserId: bookerUserId ?? null,
364	        customerName: parsed.data.customerName,
365	        customerEmail: parsed.data.customerEmail,
366	        customerPhone: parsed.data.customerPhone ?? null,
367	        date: dateStr0,
368	        startTime: parsed.data.startTime,
369	        endTime: parsed.data.endTime,
