449	      booking: bookingsTable,
450	      courtName: courtsTable.name,
451	      facilityOwnerUserId: facilitiesTable.ownerUserId,
452	      facilityOwnerName: facilitiesTable.name,
453	      facilityOwnerEmail: facilitiesTable.email,
454	    })
455	    .from(bookingsTable)
456	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
457	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
458	    .where(eq(bookingsTable.id, params.data.id));
459	
460	  if (!rows[0]) {
461	    res.status(404).json({ error: "Booking not found" });
462	    return;
463	  }
464	
465	  const { booking, facilityOwnerUserId, courtName, facilityOwnerName: ownerName, facilityOwnerEmail: ownerEmail } = rows[0];
466	  const role = await getUserRole(userId);
467	  const isBooker = booking.bookerUserId === userId;
468	  const isCourtOwner = facilityOwnerUserId === userId;
469	
470	  if (role !== "admin" && !isBooker && !isCourtOwner) {
471	    res.status(403).json({ error: "Forbidden" });
472	    return;
473	  }
474	
475	  if (booking.status === "cancelled") {
476	    res.json(CancelBookingResponse.parse(formatBooking(booking)));
477	    return;
478	  }
479	
480	  // ─── Refund tier calculation ─────────────────────────────────────────────
481	  // Policy applies uniformly to all roles. No silent admin override.
482	  const totalPriceEur = Number(booking.totalPrice);
483	  const hours = hoursBeforeStart(booking.date, booking.startTime);
484	  const tier = computeRefund(totalPriceEur, hours);
485	
486	  // Prevent cancelling a booking that has already started/ended.
487	  if (hours <= 0) {
488	    res.status(400).json({ error: "Booking has already started or ended", code: "CANCEL_TOO_LATE" });
489	    return;
490	  }
491	
492	  // ─── Atomic compare-and-set on status to prevent double-refund ──────────
493	  // Only proceed if we successfully transitioned status from non-cancelled to cancelled.
494	  const claimed = await db
495	    .update(bookingsTable)
496	    .set({ status: "cancelled" })
497	    .where(and(eq(bookingsTable.id, params.data.id), ne(bookingsTable.status, "cancelled")))
498	    .returning();
499	
500	  if (claimed.length === 0) {
501	    // Another request beat us to it — return current state without issuing a refund.
502	    const [current] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, params.data.id));
503	    res.json(CancelBookingResponse.parse(formatBooking(current)));
504	    return;
505	  }
506	
507	  // ─── Issue Stripe refund if applicable ───────────────────────────────────
