509	  if (
510	    tier.refundable &&
511	    tier.refundAmount > 0 &&
512	    booking.stripePaymentIntentId &&
513	    !booking.stripePaymentIntentId.startsWith("mock_")
514	  ) {
515	    try {
516	      const stripe = await getUncachableStripeClient();
517	      const refund = await stripe.refunds.create(
518	        {
519	          payment_intent: booking.stripePaymentIntentId,
520	          amount: Math.round(tier.refundAmount * 100),
521	          reason: "requested_by_customer",
522	        },
523	        { idempotencyKey: `cancel-booking-${booking.id}` },
524	      );
525	      stripeRefundId = refund.id;
526	      logger.info(
527	        { bookingId: booking.id, refundId: refund.id, amount: tier.refundAmount },
528	        "Stripe refund issued",
529	      );
530	    } catch (err) {
531	      logger.error({ err, bookingId: booking.id }, "Stripe refund failed");
532	      // Roll back the status transition so admin can retry / investigate.
533	      await db
534	        .update(bookingsTable)
535	        .set({ status: booking.status })
536	        .where(eq(bookingsTable.id, booking.id));
537	      res.status(502).json({ error: "Refund failed at payment provider" });
538	      return;
539	    }
540	  }
541	
542	  const [cancelled] = await db
543	    .update(bookingsTable)
544	    .set({
545	      refundAmount: String(tier.refundAmount),
546	      stripeRefundId,
547	    })
548	    .where(eq(bookingsTable.id, params.data.id))
549	    .returning();
550	
551	  // ─── Notifications (fire-and-forget; never block the response) ───────────
552	  const displayCourtName = courtName ?? "Kortas";
553	  const dateStr = typeof booking.date === "string" ? booking.date : String(booking.date);
554	
555	  // Dedupe in-app notifications: if owner and booker are the same user, only send once.
