569	      "/bookings",
570	    ).catch((err) => logger.error({ err, bookingId: booking.id }, "booker cancel notification failed"));
571	  }
572	
573	  if (facilityOwnerUserId && facilityOwnerUserId !== userId && !notifiedUserIds.has(facilityOwnerUserId)) {
574	    sendNotification(
575	      facilityOwnerUserId,
576	      "booking_cancelled",
577	      `Atšaukta rezervacija — ${displayCourtName}`,
578	      `${booking.customerName} atšaukė ${dateStr} ${booking.startTime}–${booking.endTime}.${
579	        tier.refundAmount > 0 ? ` Grąžinta klientui: ${tier.refundAmount.toFixed(2)} €.` : ""
580	      }`,
581	      "/owner",
582	    ).catch((err) => logger.error({ err, bookingId: booking.id }, "owner cancel notification failed"));
583	  }
584	
585	  // Email the customer with refund details
