1	import { Router, type IRouter } from "express";
2	import { and, eq, ne, sql } from "drizzle-orm";
3	import { db, bookingsTable, courtsTable, userProfilesTable, facilitiesTable, gamesTable } from "@workspace/db";
4	import {
5	  CreateCheckoutSessionBody,
6	  CreateCheckoutSessionResponse,
7	  ConfirmPaymentBody,
8	  ConfirmPaymentResponse,
9	} from "@workspace/api-zod";
10	import { logger } from "../lib/logger";
11	import { sendBookingConfirmationEmail, sendOwnerBookingNotificationEmail } from "../lib/email";
12	import { getUncachableStripeClient, getStripePublishableKey } from "../stripeClient";
13	import { getCurrentUserId, requireAuth, getUserRole } from "../lib/auth";
14	import { timingSafeEqualToken } from "../lib/guestToken";
15	
16	const router: IRouter = Router();
17	
18	// ─── Publishable key (safe for frontend) ─────────────────────────────────────
19	router.get("/payments/config", async (_req, res) => {
20	  try {
21	    const publishableKey = await getStripePublishableKey();
22	    res.json({ publishableKey });
23	  } catch (err) {
24	    logger.error({ err }, "Failed to get Stripe publishable key");
25	    res.status(500).json({ error: "Stripe not configured" });
26	  }
27	});
28	
29	// ─── Create Checkout Session (player or guest booking) ───────────────────────
30	// No requireAuth: a guest booking has no Clerk session, so we authorize via the
31	// `managementToken` (returned to the client when the booking was created).
32	// Authenticated callers are still authorized via session as before.
33	router.post("/payments/create-checkout", async (req, res): Promise<void> => {
34	  const parsed = CreateCheckoutSessionBody.safeParse(req.body);
35	  if (!parsed.success) {
36	    res.status(400).json({ error: parsed.error.message });
37	    return;
38	  }
39	
40	  const { bookingId, successUrl, cancelUrl } = parsed.data;
41	  // Guest checkout passes the management token in the body (CreateCheckoutSessionBody
42	  // doesn't list it, so read it raw — we never trust it without comparing to DB).
43	  const providedToken =
44	    typeof (req.body as any)?.managementToken === "string"
45	      ? ((req.body as any).managementToken as string)
46	      : null;
47	
48	  const rows = await db
49	    .select({ booking: bookingsTable, court: courtsTable, facility: facilitiesTable })
50	    .from(bookingsTable)
51	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
52	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
53	    .where(eq(bookingsTable.id, bookingId));
54	
55	  if (!rows[0]) {
56	    res.status(404).json({ error: "Booking not found" });
57	    return;
58	  }
59	
60	  const { booking, court, facility } = rows[0];
61	
62	  // Authorization:
63	  // 1) Authenticated booker / court owner / admin (existing behavior), OR
64	  // 2) Guest path: booking.bookerUserId is null AND request supplied the matching managementToken.
65	  const callerId = getCurrentUserId(req);
66	  let authorized = false;
67	  if (callerId) {
68	    const isBooker = booking.bookerUserId === callerId;
69	    const isCourtOwner = facility?.ownerUserId === callerId;
70	    const callerRole = await getUserRole(callerId);
71	    authorized = isBooker || isCourtOwner || callerRole === "admin";
72	  }
73	  if (!authorized && booking.bookerUserId === null && timingSafeEqualToken(providedToken, booking.managementToken)) {
74	    authorized = true;
75	  }
76	  if (!authorized) {
77	    res.status(403).json({ error: "Forbidden" });
78	    return;
79	  }
80	
81	  const linkGameIdRaw = (req.body as any).linkGameId;
82	  const linkGameId: number | null = Number.isInteger(linkGameIdRaw) && linkGameIdRaw > 0 ? linkGameIdRaw : null;
83	
84	  let stripe: any;
85	  try {
86	    stripe = await getUncachableStripeClient();
87	  } catch (err) {
88	    logger.warn("Stripe not configured — using mock checkout");
89	    const mockSessionId = `mock_session_${bookingId}_${Date.now()}`;
90	    await db
91	      .update(bookingsTable)
92	      .set({ stripeSessionId: mockSessionId, status: "confirmed" })
93	      .where(eq(bookingsTable.id, bookingId));
94	    await db
95	      .update(courtsTable)
96	      .set({ totalBookings: sql`total_bookings + 1` })
97	      .where(eq(courtsTable.id, booking.courtId));
98	    if (linkGameId && booking.bookerUserId) {
99	      const [game] = await db.select({ creatorUserId: gamesTable.creatorUserId })
100	        .from(gamesTable).where(eq(gamesTable.id, linkGameId));
101	      if (game && game.creatorUserId === booking.bookerUserId) {
102	        const toMin = (t: string) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
103	        await db.update(gamesTable)
104	          .set({
105	            bookingId: booking.id,
106	            courtId: booking.courtId,
107	            facilityId: facility?.id ?? null,
108	            placeName: court?.name ?? null,
109	            city: facility?.city ?? "",
110	            datetime: `${booking.date}T${booking.startTime}:00`,
111	            durationMinutes: toMin(booking.endTime) - toMin(booking.startTime),
112	          })
113	          .where(eq(gamesTable.id, linkGameId));
114	      }
115	    }
116	    const mockSuccessUrl = `${successUrl}${successUrl.includes("?") ? "&" : "?"}session_id=${mockSessionId}`;
117	    res.json(CreateCheckoutSessionResponse.parse({ sessionId: mockSessionId, url: mockSuccessUrl }));
118	    return;
119	  }
120	
121	  const amountCents = Math.round(Number(booking.totalPrice) * 100);
122	
123	  // Resolve payout destination: use the court owner's Connect account.
124	  let connectAccountId: string | null = null;
125	  if (facility?.ownerUserId) {
126	    const [profile] = await db
127	      .select({ stripeAccountId: userProfilesTable.stripeAccountId, status: userProfilesTable.stripeAccountStatus })
128	      .from(userProfilesTable)
129	      .where(eq(userProfilesTable.userId, facility.ownerUserId));
130	    if (profile?.stripeAccountId && profile.status === "active") {
131	      connectAccountId = profile.stripeAccountId;
132	    }
133	  }
134	
135	  const sessionParams: any = {
136	    payment_method_types: ["card"],
137	    line_items: [
138	      {
139	        price_data: {
140	          currency: "eur",
141	          product_data: {
142	            name: `${court?.name ?? "Kortas"} – rezervacija`,
143	            description: `${booking.date} · ${booking.startTime}–${booking.endTime}`,
144	          },
145	          unit_amount: amountCents,
146	        },
147	        quantity: 1,
148	      },
149	    ],
150	    mode: "payment",
151	    success_url: `${successUrl}${successUrl.includes("?") ? "&" : "?"}session_id={CHECKOUT_SESSION_ID}`,
152	    cancel_url: cancelUrl,
153	    metadata: { bookingId: String(bookingId), ...(linkGameId ? { linkGameId: String(linkGameId) } : {}) },
154	    customer_email: booking.customerEmail,
155	    locale: "lt",
156	  };
157	
158	  // If court owner has Stripe Connect, route payment through their account
159	  if (connectAccountId) {
160	    const platformFeePercent = 5; // 5% platform fee
161	    const applicationFeeAmount = Math.round(amountCents * platformFeePercent / 100);
162	    sessionParams.payment_intent_data = {
163	      application_fee_amount: applicationFeeAmount,
164	      transfer_data: { destination: connectAccountId },
165	    };
166	  }
167	
168	  const session = await stripe.checkout.sessions.create(sessionParams);
169	  await db.update(bookingsTable).set({ stripeSessionId: session.id }).where(eq(bookingsTable.id, bookingId));
170	
171	  res.json(CreateCheckoutSessionResponse.parse({ sessionId: session.id, url: session.url! }));
172	});
173	
174	// ─── Confirm payment after redirect ──────────────────────────────────────────
175	router.post("/payments/confirm", async (req, res): Promise<void> => {
176	  const parsed = ConfirmPaymentBody.safeParse(req.body);
177	  if (!parsed.success) {
178	    res.status(400).json({ error: parsed.error.message });
179	    return;
180	  }
181	
182	  const { sessionId } = parsed.data;
183	
184	  const rows = await db
185	    .select({
186	      booking: bookingsTable,
187	      courtName: courtsTable.name,
188	      courtId: courtsTable.id,
189	      courtAddress: facilitiesTable.address,
190	      courtCity: facilitiesTable.city,
191	      courtPhone: courtsTable.phone,
192	      courtImageUrl: courtsTable.imageUrl,
193	      ownerName: facilitiesTable.name,
194	      ownerEmail: facilitiesTable.email,
195	      facilityId: facilitiesTable.id,
196	      instantBookingEnabled: courtsTable.instantBookingEnabled,
197	    })
198	    .from(bookingsTable)
199	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
200	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
201	    .where(eq(bookingsTable.stripeSessionId, sessionId));
202	
203	  if (!rows[0]) {
204	    res.status(404).json({ error: "Booking not found for session" });
205	    return;
206	  }
207	
208	  let linkGameId: number | null = null;
209	  let stripePaymentIntentId: string | null = null;
210	  if (!sessionId.startsWith("mock_")) {
211	    try {
212	      const stripe = await getUncachableStripeClient();
213	      const session = await stripe.checkout.sessions.retrieve(sessionId);
214	      if (session.payment_status !== "paid") {
215	        res.status(402).json({ error: "Payment not completed" });
216	        return;
217	      }
218	      stripePaymentIntentId =
219	        typeof session.payment_intent === "string"
220	          ? session.payment_intent
221	          : session.payment_intent?.id ?? null;
222	      const lgId = session.metadata?.linkGameId;
223	      if (lgId) linkGameId = parseInt(lgId, 10);
224	    } catch (err) {
225	      logger.error({ err }, "Stripe retrieve session error");
226	    }
227	  }
228	
229	  const newStatus = "confirmed";
230	
231	  // Idempotent transition: only the first caller (race between Stripe webhook and
232	  // the eager success-page POST) actually flips status and runs side effects.
233	  // Subsequent calls return the already-confirmed booking without re-incrementing
234	  // counters or re-sending emails.
235	  const updated = await db
236	    .update(bookingsTable)
237	    .set({
238	      status: newStatus,
239	      ...(stripePaymentIntentId ? { stripePaymentIntentId } : {}),
240	    })
241	    .where(and(
242	      eq(bookingsTable.stripeSessionId, sessionId),
243	      ne(bookingsTable.status, "confirmed"),
244	    ))
245	    .returning();
246	
247	  if (updated.length === 0) {
248	    // Already confirmed by webhook (or another concurrent call). Return current state.
249	    res.json(ConfirmPaymentResponse.parse({
250	      ...rows[0].booking,
251	      totalPrice: Number(rows[0].booking.totalPrice),
252	      refundAmount: Number(rows[0].booking.refundAmount ?? 0),
253	      pricePerSlot: rows[0].booking.pricePerSlot != null ? Number(rows[0].booking.pricePerSlot) : undefined,
254	      totalSlots: rows[0].booking.totalSlots ?? undefined,
255	      splitInviteToken: rows[0].booking.splitInviteToken ?? undefined,
256	      stripeSessionId: rows[0].booking.stripeSessionId ?? undefined,
257	      stripeRefundId: rows[0].booking.stripeRefundId ?? undefined,
258	      rentedItems: rows[0].booking.rentedItems ?? undefined,
259	      courtName: rows[0].courtName ?? undefined,
260	      status: "confirmed",
261	    }));
262	    return;
263	  }
264	
265	  const booking = updated[0];
266	
267	  if (linkGameId && booking.bookerUserId) {
268	    const [game] = await db.select({ creatorUserId: gamesTable.creatorUserId })
269	      .from(gamesTable).where(eq(gamesTable.id, linkGameId));
270	    if (game && game.creatorUserId === booking.bookerUserId) {
271	      const toMin = (t: string) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
272	      await db.update(gamesTable)
273	        .set({
