421	      const session = await stripe.checkout.sessions.retrieve(sessionId);
422	      if (session.payment_status !== "paid") {
423	        res.status(402).json({ error: "Payment not completed" });
424	        return;
425	      }
426	      const lgId = session.metadata?.linkGameId;
427	      if (lgId) linkGameId = parseInt(lgId, 10);
428	    } catch (err) {
429	      logger.error({ err }, "Stripe retrieve session error in confirm-split");
430	    }
431	  }
