446	  // Move booking to awaiting_players (from pending) — track if this is a fresh transition
447	  let justTransitioned = false;
448	  if (booking.status === "pending") {
449	    const updated = await db
450	      .update(bookingsTable)
451	      .set({ status: "awaiting_players" })
452	      .where(and(eq(bookingsTable.id, booking.id), eq(bookingsTable.status, "pending")))
453	      .returning();
454	    justTransitioned = updated.length > 0;
455	  }
