      paidSlots: paidCount,
      totalSlots: booking.totalSlots ?? 1,
      bookingId: booking.id,
    }).catch((err) => logger.error({ err }, "sendSplitPlayerJoinedEmail (webhook) failed"));
  }

  // Send confirmation email to the participant
