  const handleGuestJoin = async () => {
    if (!info || !token) return;
    const name = guestName.trim();
    const email = guestEmail.trim();
    if (!name || !email) {
      toast({ title: "Klaida", description: "Įveskite vardą ir el. paštą.", variant: "destructive" });
