243	/** Returns true if the current request's userId matches the court owner (or is admin) */
244	export async function isOwner(req: Request, ownerUserId: string | null | undefined): Promise<boolean> {
245	  if (isAgentBypass(req)) {
246	    const r = bypassRole(req);
247	    if (r === "admin") return true;
248	    if (r === "owner" && ownerUserId && ownerUserId === bypassUserId(req)) return true;
249	    return false;
250	  }
251	  const { userId } = getAuth(req);
252	  if (!userId) return false;
253	  if (ownerUserId && ownerUserId === userId) return true;
254	  // Admins can act as owners
255	  const role = await getUserRole(userId);
256	  return role === "admin";
257	}
